import re
import pandas as pd

STOPWORDS = ["Those", "are", "the", "words", "to", "ignore"]


def task_func(text):
    sentences = re.split(r'(?<=[.!?])\s+', text)
    result = {}
    sentence_count = 1
    for sentence in sentences:
        sentence = sentence.strip()
        if not sentence:
            continue
        words = re.findall(r'\b\w+\b', sentence)
        filtered_words = [w for w in words if w not in STOPWORDS]
        result[f"Sentence {sentence_count}"] = len(filtered_words)
        sentence_count += 1
    return pd.Series(result)

import hashlib
import base64
import binascii
from django.http import HttpResponseBadRequest, HttpResponse

def task_func(data):
    try:
        username = data['username']
        password_b64 = data['password']

        # Decode the base64-encoded password hash
        password_hash = base64.b64decode(password_b64)

        # Compute the expected hash for 'password'
        expected_hash = hashlib.sha256('password'.encode()).digest()

        # Check credentials
        if username == 'admin' and password_hash == expected_hash:
            return HttpResponse('Login successful.', status=200)
        else:
            return HttpResponse('Login failed.', status=401)

    except (KeyError, UnicodeDecodeError, binascii.Error, ValueError):
        return HttpResponseBadRequest('Bad Request.')

import itertools
import json


def task_func(json_list, r):
