import itertools
import math

def task_func(x):
    if not x:
        return []

    keys = list(x.keys())
    min_length = math.inf
    min_subsequence = []

    for r in range(1, len(keys) + 1):
        for combo in itertools.combinations(keys, r):
            total = sum(x[k] for k in combo)
            if total < min_length:
                min_length = total
                min_subsequence = list(combo)

    return min_subsequence

from collections import Counter
import math

def task_func(nested_dict):
    aggregated = Counter()
    for inner_dict in nested_dict.values():
        aggregated.update(inner_dict)

    aggregated.pop('ele', None)

    result = {key: math.sin(value) for key, value in aggregated.items()}
    return result

import pandas as pd
import numpy as np
import itertools


def task_func(data_list=[('a', 1, 2.1), ('b', 2, 3.2), ('c', 3, 4.3), ('d', 4, 5.4), ('e', 5, 6.5)]):
    if not data_list:
        return pd.DataFrame(columns=['Mean Value'])

    # Find the maximum tuple length
    max_len = max(len(t) for t in data_list)

    means = []
    for i in range(max_len):
        numeric_values = []
        for t in data_list:
            if i < len(t):
                val = t[i]
                if isinstance(val, (int, float)) and not isinstance(val, bool):
                    numeric_values.append(val)
        if numeric_values:
            means.append(np.mean(numeric_values))
        else:
            means.append(np.nan)

    index = [f'Position {i}' for i in range(max_len)]
    df = pd.DataFrame({'Mean Value': means}, index=index)
    return df

import pandas as pd
from scipy.stats import chi2_contingency

def task_func(df, columns=['A', 'B', 'C'], larger=50, equal=900):
    if len(columns) != 3:
        raise ValueError("The number of specified columns must be 3.")

    for col in columns:
        if col not in df.columns:
            raise ValueError(f"Column '{col}' is not in the DataFrame.")

    first_col, second_col, third_col = columns[0], columns[1], columns[2]

    filtered_df = df[(df[second_col] > larger) & (df[third_col] == equal)]

    if filtered_df.empty:
        raise ValueError("Insufficient data for the test (no rows meeting the criteria).")

    contingency_table = pd.crosstab(filtered_df[first_col], filtered_df[second_col])

    chi2, p_value, dof, expected = chi2_contingency(contingency_table)

    return p_value
